<a class="back-link" href="<?= e(url('/stories/' . $story['id'])) ?>">← К истории</a><div class="page-heading"><p class="eyebrow">Последний штрих</p><h1>Редактирование истории</h1><p>Количество страниц сохранится. После изменений PDF будет сформирован заново.</p></div><section class="form-panel editor-form"><?php if ($errors): ?><div class="notice error" role="alert"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" action="<?= e(url('/stories/' . $story['id'] . '/edit')) ?>"><?= csrf_field() ?><label class="field">Название истории<input name="title" maxlength="120" value="<?= e($story['title']) ?>" required></label><?php foreach ($story['pages'] as $index => $page): ?><fieldset class="edit-page"><legend>Страница <?= $index + 1 ?></legend><label class="field">Название главы<input name="pages[<?= $index ?>][heading]" maxlength="90" value="<?= e($page['heading']) ?>" required></label><label class="field">Текст страницы<textarea name="pages[<?= $index ?>][text]" rows="13" minlength="100" maxlength="2600" required><?= e($page['text']) ?></textarea></label></fieldset><?php endforeach; ?><button class="button" type="submit">Сохранить изменения</button></form></section>
